'use strict';
const $=(s,root=document)=>root.querySelector(s);
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const N=(v,d=2)=>v==null||!Number.isFinite(Number(v))?'—':Number(v).toLocaleString('en-IN',{maximumFractionDigits:d,minimumFractionDigits:d});
const P=v=>v==null?'—':`${v>0?'+':''}${N(v)}%`;
const D=v=>!v?'Not available':new Date(v.length===10?v+'T00:00:00Z':v).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});
const T=v=>!v?'Not checked':new Date(v).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
const money=v=>v==null?'—':'₹'+N(v,0);
const cls=v=>v==null?'muted':v>=0?'positive':'negative';
const state={funds:[],status:null,search:'',plan:'Direct',option:'Growth',sort:'aum',page:1,token:0,fund:null,perf:null,tab:'overview',range:'3Y',benchmark:'Nifty Smallcap 250 TRI',chartMode:'comparison',newsFilter:'All',importCode:0};
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',6000);}
const HOSTED=window.SMALLCAP_CONFIG?.mode==='github';
async function api(url,options={}){if(HOSTED)return window.SmallcapStatic.request(url,options);const r=await fetch(url,{...options,headers:{'X-Smallcap-Client':'local',...(options.body&&!(options.body instanceof FormData)?{'Content-Type':'application/json'}:{}),...options.headers}});if(!r.ok){let msg;try{msg=(await r.json()).detail;}catch{msg=r.statusText;}throw Error(typeof msg==='string'?msg:JSON.stringify(msg));}return r.json();}
const post=(url,body)=>api(url,{method:'POST',body:JSON.stringify(body)});
function metric(label,value,sub,featured=false){return `<div class="metric-card ${featured?'featured':''}"><div class="metric-label">${E(label)}</div><div class="metric-value mono">${value}</div><div class="metric-sub">${sub}</div></div>`;}
function empty(title,message,action=''){return `<div class="empty"><h3>${E(title)}</h3><p>${E(message)}</p>${action}</div>`;}
function sourceLink(url,label='Source'){return url?`<a href="${E(url)}" target="_blank" rel="noopener noreferrer">${E(label)} ↗</a>`:'';}
function mark(name){return name.split(' ').filter(x=>!['Small','Cap','Fund','India'].includes(x)).slice(0,2).map(x=>x[0]).join('').toUpperCase();}
function metricValue(m){return m?E(m.value):'<span class="muted">Not available</span>';}
function feeFor(s){const ms=s.metrics||{};return ms.ter||ms.ter_observed||ms.base_expense_ratio||ms.expense_ratio;}
function busy(){const jobs=state.status?.running||{};return Object.keys(jobs).length?`<div class="busy-strip"><span class="spinner" aria-hidden="true"></span><span>${E(Object.values(jobs).map(x=>x.detail).join(' · '))}</span></div>`:'';}

function shell(){
  $('#app').innerHTML=`<div class="layout"><aside class="sidebar"><a class="brand" href="#/"><span class="brand-icon">S</span>Smallcap Ledger</a><div class="side-caption">Your fund research desk</div><nav class="nav" aria-label="Main navigation"><a href="#/" data-nav="funds"><span class="nav-icon">▦</span> All funds</a><a href="#/archive" data-nav="archive"><span class="nav-icon">▤</span> Data & archive</a><a href="#/settings" data-nav="settings"><span class="nav-icon">⚙</span> Update settings</a></nav><div class="side-section">Fund category</div><div class="category"><span></span>Small-cap equity</div><div class="sidebar-bottom">${HOSTED?'<strong>Daily at midnight IST</strong>Updates run on GitHub.<br>No open browser needed.':'<strong>Local to your computer</strong>History stays here.<br>Updates while running.'}</div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb" id="breadcrumb">Research / Small-cap funds</div><div class="top-actions"><span class="local-badge">${HOSTED?'DAILY ARCHIVE':'LOCAL ARCHIVE'}</span><button id="refresh-all">↻ &nbsp; Update data</button></div></header><main class="main" id="main" tabindex="-1"></main></div></div>`;
  $('#refresh-all').addEventListener('click',async()=>{if(HOSTED){await pollStatus();await route();toast('Loaded the latest published data. The daily update runs on GitHub.');return;}try{await post('/api/refresh',{kind:'all'});toast('Updates started. Saved data stays available.');await pollStatus();}catch(e){toast(e.message);}});
}
function selectedNav(path){document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===path));}
async function loadFunds(){const r=await api('/api/funds');state.funds=r.funds;}
async function route(){
  const token=++state.token;const parts=(location.hash||'#/').split('/');const page=parts[1]||'';
  $('#main').innerHTML='<div class="loading"><span class="spinner"></span> Opening your archive…</div>';
  try{
    if(page==='fund'){
      selectedNav('funds');const code=Number(parts[2]);state.tab=parts[3]||'overview';
      if(!['overview','performance','portfolio','fees','news'].includes(state.tab))state.tab='overview';
      const f=await api('/api/funds/'+code);if(token!==state.token)return;const official=f.metrics.benchmark?.value||'';if(state.fund?.family!==f.family){const stated=/bse.*250.*small/i.test(official)?'BSE 250 SmallCap TRI':'Nifty Smallcap 250 TRI';state.benchmark=state.status?.benchmarks?.some(b=>b.name===stated&&b.points>1)?stated:'Nifty Smallcap 250 TRI';}state.fund=f;state.importCode=code;
      await renderFund(token);
    }else if(page==='archive'){selectedNav('archive');await loadFunds();if(token!==state.token)return;renderArchive();}
    else if(page==='settings'){selectedNav('settings');if(HOSTED)renderHostedSettings();else renderSettings();}
    else{selectedNav('funds');await loadFunds();if(token!==state.token)return;renderDashboard();}
  }catch(e){if(token===state.token)$('#main').innerHTML=empty('Could not open this view',e.message,'<button id="retry">Try again</button>');$('#retry')?.addEventListener('click',route);}
}

function renderDashboard(){
  $('#breadcrumb').textContent='Research / Small-cap funds';document.title='Small-cap funds · Smallcap Ledger';
  const c=state.status?.counts||{};const dates=state.funds.map(f=>f.nav?.date).filter(Boolean).sort();const last=dates.at(-1);
  $('#main').innerHTML=`<div class="page-heading"><div><div class="eyebrow">Indian mutual funds</div><h1>Small-cap mutual funds</h1><p>Compare NAV, fund size, expense ratios and performance.</p></div><div class="page-actions"><span class="badge">NAV ${last?D(last):'awaiting first update'}</span></div></div><div id="busy-area">${busy()}</div><div class="metrics">${metric('Small-cap funds',N(c.funds||0,0),'AMFI small-cap equity category',true)}${metric('Plans & options',N(c.plans||0,0),'Distinct NAV series · IDCW included')}${metric('AUM coverage',N(new Set(state.funds.filter(f=>f.metrics.aum).map(f=>f.family)).size,0)+' / '+N(c.funds||0,0),'Funds with a sourced AUM figure')}${metric('Expense ratio coverage',N(new Set(state.funds.filter(f=>feeFor(f)).map(f=>f.family)).size,0)+' / '+N(c.funds||0,0),'Funds with a reported or observed fee')}</div><section class="panel no-pad"><div class="panel-head table-head"><h2>Fund directory</h2><span class="small muted" id="result-count"></span></div><div class="filters"><input id="search-funds" placeholder="Search a fund or fund house" aria-label="Search funds" value="${E(state.search)}"><select id="plan-filter" aria-label="Filter plan">${[...new Set(['All','Direct','Regular',...state.funds.map(f=>f.plan)])].map(x=>`<option ${state.plan===x?'selected':''} value="${x}">${x==='All'?'All plans':x}</option>`).join('')}</select><select id="option-filter" aria-label="Filter option">${[...new Set(['All','Growth','IDCW',...state.funds.map(f=>f.option)])].map(x=>`<option ${state.option===x?'selected':''} value="${x}">${x==='All'?'All options':x}</option>`).join('')}</select><select id="sort-funds" aria-label="Sort funds">${[['family','Fund name'],['3','3Y return: high to low'],['1','1Y return: high to low'],['aum','AUM: high to low'],['ter','Fee: low to high']].map(([v,t])=>`<option value="${v}" ${state.sort===v?'selected':''}>${t}</option>`).join('')}</select></div><div id="fund-table"></div></section><p class="footer-note">NAV change is relative to the previous stored observation. Growth returns use published NAVs after fund expenses; returns of one year and longer are annualized. IDCW return cells stay empty until complete distribution history is supplied. Bonus options require unit-adjustment history. BER and TER are labelled separately. A fee labelled ‘reported’ has no TER/BER breakdown in its source. Missing AUM and fees are shown as gaps. NAV availability does not confirm whether fresh investments are currently accepted.</p>`;
  for(const [id,key] of [['search-funds','search'],['plan-filter','plan'],['option-filter','option'],['sort-funds','sort']])$('#'+id).addEventListener(id==='search-funds'?'input':'change',e=>{state[key]=e.target.value;state.page=1;fundTable();});
  fundTable();
}
function fundTable(){
  let rows=state.funds.filter(f=>(f.name+' '+f.amc).toLowerCase().includes(state.search.toLowerCase())&&(state.plan==='All'||f.plan===state.plan)&&(state.option==='All'||f.option===state.option));
  if(state.sort==='family')rows.sort((a,b)=>a.family.localeCompare(b.family)||a.plan.localeCompare(b.plan)||a.option.localeCompare(b.option));
  else rows.sort((a,b)=>{const v=f=>state.sort==='aum'?Number(f.metrics.aum?.value??-Infinity):state.sort==='ter'?Number(feeFor(f)?.value??Infinity):f.returns[state.sort]??-Infinity;return state.sort==='ter'?v(a)-v(b):v(b)-v(a);});
  const pages=Math.max(1,Math.ceil(rows.length/25));state.page=Math.min(state.page,pages);const shown=rows.slice((state.page-1)*25,state.page*25);
  $('#result-count').textContent=rows.length+' NAV series';
  $('#fund-table').innerHTML=!rows.length?empty(state.funds.length?'No matching funds':'Your first update is getting started',state.funds.length?'Try another search or plan filter.':'The updater downloads the official small-cap category, then builds NAV and document history. You can keep this page open.'):`<div class="table-wrap"><table class="fund-table"><thead><tr><th>Fund / plan</th><th class="right">NAV</th><th class="right">AUM · ₹ Cr</th><th class="right">Expense ratio</th><th class="right">NAV change</th><th class="right">1Y return</th><th class="right">3Y CAGR</th><th>Data coverage</th></tr></thead><tbody>${shown.map(f=>{const fee=feeFor(f);return `<tr><td><div class="fund-name"><span class="fund-mark">${mark(f.family)}</span><div><a class="fund-title" href="#/fund/${f.code}">${E(f.family)}</a><div class="fund-detail">${E(f.plan)} · ${E(f.option_label||f.option)}</div></div></div></td><td data-label="NAV" class="right"><b>₹${N(f.nav?.value,4)}</b><div class="fund-detail">${f.nav?D(f.nav.date):'Unavailable'}</div></td><td data-label="AUM · ₹ Cr" class="right">${N(f.metrics.aum?.value,0)}<div class="fund-detail">${f.metrics.aum?D(f.metrics.aum.as_of):'Not available'}</div></td><td data-label="Expense ratio" class="right">${fee?N(fee.value)+'% '+(fee.metric==='base_expense_ratio'?'BER':fee.metric==='expense_ratio'?'reported':'TER'):'—'}<div class="fund-detail">${fee?fee.metric==='ter_observed'?'Observed '+D(fee.as_of):D(fee.as_of):'Not available'}</div></td><td data-label="NAV change" class="right ${cls(f.nav_change)}">${P(f.nav_change)}</td><td data-label="1Y return" class="right ${cls(f.returns['1'])}">${P(f.returns['1'])}</td><td data-label="3Y CAGR" class="right ${cls(f.returns['3'])}">${P(f.returns['3'])}</td><td><span class="badge ${f.stale_days>4?'amber':f.coverage.points>30?'green':''}">${f.stale_days>4?'Older NAV':f.coverage.points>30?'History saved':'Building history'}</span><div class="fund-detail">${f.portfolio?'Portfolio '+D(f.portfolio.as_of):'Portfolio gap'}</div></td></tr>`;}).join('')}</tbody></table></div><div class="pagination"><span>${(state.page-1)*25+1}–${Math.min(state.page*25,rows.length)} of ${rows.length}</span><div><button id="prev" ${state.page===1?'disabled':''}>← Previous</button><span>${state.page} / ${pages}</span><button id="next" ${state.page===pages?'disabled':''}>Next →</button></div></div>`;
  $('#prev')?.addEventListener('click',()=>{state.page--;fundTable();});$('#next')?.addEventListener('click',()=>{state.page++;fundTable();});
}
function rangeStart(){if(state.range==='All')return '';if(state.range==='Custom')return state.customStart||'';const latest=state.fund?.nav_coverage?.last||new Date().toISOString().slice(0,10);return window.SmallcapAnalytics.shift(latest,parseInt(state.range)*(state.range.endsWith('Y')?12:1));}
async function getPerformance(){const q=new URLSearchParams({benchmark:state.benchmark,monthly:String(state.monthly||10000)});const s=rangeStart();if(s)q.set('start',s);if(state.range==='Custom'&&state.customEnd)q.set('end',state.customEnd);return api(`/api/funds/${state.fund.code}/performance?${q}`);}
function fundHeader(){const f=state.fund;return `<div class="page-heading"><div><div class="eyebrow">Small-cap equity · ${E(f.amc)}</div><div class="fund-heading"><span class="fund-mark">${mark(f.family)}</span><div><h1>${E(f.family)}</h1><p>${E(f.plan)} · ${E(f.option_label||f.option)} <span class="badge">AMFI ${f.code}</span></p></div></div></div><div class="page-actions"><label><span class="small muted">Plan and option</span><select id="plan-picker" class="plan-picker">${f.plans.map(p=>`<option value="${p.code}" ${p.code===f.code?'selected':''}>${E(p.plan)} · ${E(p.option_label||p.option)} (${p.code})</option>`).join('')}</select></label></div></div><nav class="tabs" aria-label="Fund sections">${[['overview','Overview'],['performance','Performance'],['portfolio','Portfolio'],['fees','Fees & history'],['news','Fund communications']].map(([v,t])=>`<a class="${state.tab===v?'active':''}" href="#/fund/${f.code}/${v}">${t}</a>`).join('')}</nav><div id="busy-area">${busy()}</div><div id="fund-content"></div>`;}
async function renderFund(token){const f=state.fund;document.title=f.family+' · Smallcap Ledger';$('#breadcrumb').innerHTML=`<a href="#/">All funds</a> / ${E(f.family)}`;$('#main').innerHTML=fundHeader();$('#plan-picker').addEventListener('change',e=>location.hash=`/fund/${e.target.value}/${state.tab}`);const el=$('#fund-content');
  if(state.tab==='news'){const docs=await api(`/api/funds/${f.code}/documents`);if(token!==state.token)return;renderNews(docs);}
  else if(state.tab==='portfolio'){await renderPortfolio();}
  else if(state.tab==='fees'){renderFees();}
  else{el.innerHTML='<div class="loading">Loading performance history…</div>';const p=await getPerformance();if(token!==state.token)return;state.perf=p;if(state.tab==='overview')renderOverview();else renderPerformance();}
}
function renderOverview(){const f=state.fund,p=state.perf,m=f.metrics,fee=feeFor(f),last=p.latest_nav;const ret=p.stats.returns['3Y'];
  $('#fund-content').innerHTML=`<div class="metrics">${metric('Latest NAV',last?'₹'+N(last[1],4):'—',last?D(last[0]):'Awaiting NAV',true)}${metric('Fund AUM',m.aum?'₹'+N(m.aum.value,0)+' Cr':'—',m.aum?'As of '+D(m.aum.as_of)+' · '+sourceLink(m.aum.source)+(m.aum.source_note?'<br>'+E(m.aum.source_note):''):'Unavailable from connected sources')}${metric(fee?.metric==='base_expense_ratio'?'Base expense ratio (BER)':fee?.metric==='expense_ratio'?'Expense ratio (reported)':'Total expense ratio (TER)',fee?N(fee.value)+'%':'—',fee?(fee.metric==='ter_observed'?'Observed ':'As of ')+D(fee.as_of)+' · '+sourceLink(fee.source)+(fee.source_note?'<br>'+E(fee.source_note):''):'Unavailable from connected sources')}${metric('3-year annualized return',ret?`<span class="${cls(ret.value)}">${P(ret.value)}</span>`:'—',ret?'Through '+D(ret.end):f.option==='Bonus'?'Requires unit-adjustment history':f.option==='IDCW'?'Requires complete distribution history':'Insufficient NAV history')}</div>${f.option!=='Growth'?`<div class="callout warning">${E(p.method)}</div>`:''}<section class="panel comparison-overview"><div class="panel-head"><div><h2>Fund vs benchmark</h2><p class="small muted">Growth of ₹100 on matching dates · ${E(state.range)}</p></div><a class="primary-link" href="#/fund/${f.code}/performance">Compare dates & returns →</a></div><div class="chart-legend"><span><i class="legend-line"></i>${E(f.plan)} · ${E(f.option)}</span><span><i class="legend-line benchmark"></i>${E(state.benchmark)}</span></div><div id="overview-comparison"></div><p class="footer-note">${benchmarkNote(f)} ${p.comparison.length?'Both series start at 100 on '+D(p.comparison[0][0])+'.':''}</p></section><div class="two-columns"><section class="panel"><div class="panel-head"><h2>NAV history</h2><a class="secondary-link" href="/api/export/nav/${f.code}">Download CSV ↓</a></div><div id="overview-chart"></div><div class="chart-foot"><span>${p.first_nav?'History begins '+D(p.first_nav):'History pending'}</span></div></section><section class="panel"><h2>Fund details</h2><dl class="facts">${[['Fund managers',m.managers],['Stated benchmark',m.benchmark],['Fund launch',m.fund_launch],['Risk level',m.risk],['Minimum SIP',m.minimum_sip]].map(([label,v])=>`<div class="fact"><dt>${label}</dt><dd>${metricValue(v)}${v?`<div class="fund-detail">${sourceLink(v.source)} · ${String(v.unit).includes('Observed')?'observed':'as of'} ${D(v.as_of)}</div>`:''}</dd></div>`).join('')}<div class="fact"><dt>Growth / payout ISIN</dt><dd>${E(f.isin||'Not supplied')}</dd></div>${f.reinvestment_isin?`<div class="fact"><dt>IDCW reinvestment ISIN</dt><dd>${E(f.reinvestment_isin)}<div class="fund-detail">Shares the published NAV series with payout.</div></dd></div>`:''}</dl></section></div><section class="panel"><h2>Investment objective</h2><div class="text-block">${m.objective?E(m.objective.value):'The objective has not yet been extracted from a readable fund document.'}</div>${m.objective?`<p class="footer-note">${sourceLink(m.objective.source)}</p>`:''}</section><section class="panel"><div class="panel-head"><h2>Coverage for this fund</h2><a href="#/archive" class="secondary-link">Fill a data gap →</a></div><div class="coverage-grid">${[['NAV history',p.first_nav?'From '+D(p.first_nav):'Awaiting download'],['AUM',m.aum?'Reported '+D(m.aum.as_of):'Missing numeric history'],['Portfolio',f.portfolios.length?f.portfolios.length+' saved snapshots':'No parsed snapshot'],['Fees',fee?'Observed/reported '+D(fee.as_of):'Not yet extracted'],['Benchmark',p.benchmark_source?.points?state.benchmark+' available':'TRI data unavailable'],['Distribution / unit adjustments',f.option==='Growth'?'Not applicable':f.option==='Bonus'?'Unit adjustments unavailable':f.distribution_coverage?'User-supplied coverage':'Distribution history unavailable']].map(([t,v])=>`<div class="coverage-item"><b>${t}</b><span>${E(v)}</span></div>`).join('')}</div></section>`;
  if(p.can_total_return)drawChart($('#overview-comparison'),p.comparison,[{label:f.plan+' '+f.option,color:'#205ade'},{label:state.benchmark,color:'#dd7940'}]);else $('#overview-comparison').innerHTML=empty('Total-return comparison unavailable',p.method);
  drawChart($('#overview-chart'),p.nav,[{label:'NAV',color:'#205ade'}],{currency:true});
}

function benchmarkNote(f){const official=f.metrics.benchmark?.value;if(!official)return 'The stated benchmark is unverified. '+E(state.benchmark)+' is shown as a category comparator.';const canonical=x=>x.toLowerCase().replace(/total[ -]*return[ -]*index/g,'tri').replace(/\bindex\b/g,'').replace(/[^a-z0-9]/g,'');const matches=canonical(official)===canonical(state.benchmark);return 'Stated benchmark: '+E(official)+'. '+(matches?'The selected series is its total-return index.':E(state.benchmark)+' is a category comparator; the stated index history is unavailable.');}

function drawChart(container,points,series,options={}){
  if(!points||points.length<2){container.innerHTML=empty('Not enough data to draw this chart','At least two observations are needed. Newly downloaded or imported records will appear here.');return;}
  const W=900,H=330,L=65,R=20,TOP=22,B=40;const dates=points.map(p=>Date.parse(p[0]));const minX=dates[0],maxX=dates.at(-1);let vals=points.flatMap(p=>p.slice(1).filter(v=>v!=null));let lo=Math.min(...vals),hi=Math.max(...vals);const pad=(hi-lo)*.1||Math.abs(hi)*.05||1;lo-=pad;hi+=pad;
  const x=d=>L+(d-minX)/(maxX-minX)*(W-L-R),y=v=>H-B-(v-lo)/(hi-lo)*(H-TOP-B);
  let grid='';for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4,py=y(v);grid+=`<line class="chart-grid" x1="${L}" x2="${W-R}" y1="${py}" y2="${py}"/><text class="chart-label" x="${L-12}" y="${py+4}" text-anchor="end">${N(v,options.percent?1:Math.abs(v)>1000?0:1)}${options.percent?'%':''}</text>`;}
  for(let i=0;i<5;i++){const dx=minX+(maxX-minX)*i/4;grid+=`<text class="chart-label" x="${x(dx)}" y="${H-8}" text-anchor="${i===0?'start':i===4?'end':'middle'}">${E(new Date(dx).toLocaleDateString('en-IN',{month:'short',year:'2-digit',timeZone:'UTC'}))}</text>`;}
  // Render every stored observation; no interpolation or synthetic points are inserted.
  const paths=series.map((s,j)=>{let d='';let previous=null;points.forEach((p,i)=>{if(p[j+1]==null){previous=null;return;}const gap=previous!==null&&!options.sparse&&(dates[i]-previous)>8*86400000;d+=(previous===null||gap?'M':'L')+x(dates[i]).toFixed(2)+','+y(p[j+1]).toFixed(2);previous=dates[i];});return `<path d="${d}" fill="none" stroke="${s.color}" stroke-width="2.5" stroke-linejoin="round"/>`;}).join('');
  container.innerHTML=`<div class="chart" tabindex="0" role="img" aria-label="${E(series.map(s=>s.label).join(' versus '))} chart, ${D(points[0][0])} to ${D(points.at(-1)[0])}. Use left and right arrow keys for values."><div class="chart-tip"></div><svg viewBox="0 0 ${W} ${H}" aria-hidden="true">${grid}${paths}<line data-guide x1="0" x2="0" y1="${TOP}" y2="${H-B}" stroke="#9aaac1" stroke-dasharray="3 4" opacity="0"/><rect x="${L}" y="${TOP}" width="${W-L-R}" height="${H-TOP-B}" fill="transparent"/></svg></div>`;
  const chart=$('.chart',container),tip=$('.chart-tip',chart),guide=$('[data-guide]',chart);let idx=points.length-1;
  function show(i){idx=Math.max(0,Math.min(points.length-1,i));const p=points[idx];tip.style.display='block';tip.innerHTML=`<b>${D(p[0])}</b>${series.map((s,j)=>`<div>${E(s.label)}: <strong>${p[j+1]==null?'—':(options.currency?'₹':'')+N(p[j+1],2)+(options.percent?'%':'')}</strong></div>`).join('')}`;guide.setAttribute('x1',x(dates[idx]));guide.setAttribute('x2',x(dates[idx]));guide.setAttribute('opacity','1');}
  chart.addEventListener('pointermove',e=>{const rect=$('svg',chart).getBoundingClientRect();const value=minX+((e.clientX-rect.left)/rect.width*W-L)/(W-L-R)*(maxX-minX);let left=0,right=dates.length-1;while(left<right){const mid=Math.floor((left+right)/2);if(dates[mid]<value)left=mid+1;else right=mid;}if(left&&Math.abs(dates[left-1]-value)<Math.abs(dates[left]-value))left--;show(left);});
  chart.addEventListener('pointerleave',()=>{tip.style.display='none';guide.setAttribute('opacity','0');});chart.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();show(idx+(e.key==='ArrowLeft'?-1:1));}});
}

function renderPerformance(){const f=state.fund,p=state.perf;const available=[...new Set(['Nifty Smallcap 250 TRI',state.benchmark,...(state.status?.benchmarks||[]).map(x=>x.name)])];
  $('#fund-content').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Performance through time</h2><div class="small muted">${E(f.plan)} · ${E(f.option)}</div></div><a class="secondary-link" href="/api/export/nav/${f.code}">Export NAV ↓</a></div><div class="chart-controls"><div class="range-buttons">${['1M','3M','6M','1Y','3Y','5Y','10Y','All'].map(r=>`<button data-range="${r}" class="${state.range===r?'active':''}">${r}</button>`).join('')}</div><select id="chart-mode" aria-label="Chart measure">${[['comparison','Fund vs benchmark · rebased 100'],['nav','NAV'],['drawdown','Drawdown'],['rolling','Rolling 3-year CAGR']].map(([v,t])=>`<option value="${v}" ${state.chartMode===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="date-controls"><label>From<input id="range-start" type="date" value="${E(rangeStart())}"></label><label>To<input id="range-end" type="date" value="${E(state.range==='Custom'?state.customEnd||'':p.last_nav||'')}"></label><button id="apply-range">Apply dates</button><label>Comparison index<select id="benchmark-select">${available.map(x=>`<option ${state.benchmark===x?'selected':''}>${E(x)}</option>`).join('')}</select></label></div><p class="footer-note">Stated benchmark: ${f.metrics.benchmark?E(f.metrics.benchmark.value):'not yet verified from a fund document'}. The selected index is a category comparator unless it matches the fund’s stated benchmark. Historical benchmark changes may not be mapped.</p><div id="chart-message"></div><div id="performance-legend" class="chart-legend"></div><div id="performance-chart"></div><div class="chart-foot"><span id="chart-interval"></span><span>${E(p.method)}</span></div><div class="mini-stats"><div><span>Maximum drawdown · selected dates</span><strong class="negative">${P(p.range_stats.max_drawdown)}</strong></div><div><span>Annualized daily volatility</span><strong>${p.range_stats.volatility==null?'—':N(p.range_stats.volatility)+'%'}</strong></div><div><span>Matched benchmark dates</span><strong>${N(p.comparison.length,0)}</strong></div></div></section><section class="panel no-pad"><div class="panel-head table-head"><h2>Returns against the comparison index</h2><span class="small muted">Full matching history through end date</span></div><div class="table-wrap"><table><thead><tr><th>Period</th><th class="right">Fund</th><th class="right">${E(state.benchmark)}</th><th class="right">Difference</th><th>Measurement dates</th></tr></thead><tbody>${['1M','3M','6M','1Y','3Y','5Y','10Y','Since start'].map(k=>{const a=p.comparison_stats.fund[k],b=p.comparison_stats.benchmark[k],diff=a&&b?a.value-b.value:null;return `<tr><td>${k==='Since start'?'Since common start':k}${a?.annualized?' CAGR':''}</td><td class="right ${cls(a?.value)}">${P(a?.value)}</td><td class="right ${cls(b?.value)}">${P(b?.value)}</td><td class="right ${cls(diff)}">${diff==null?'—':N(diff)+' pp'}</td><td class="small muted">${a?D(a.start)+' – '+D(a.end):'Insufficient matching history'}</td></tr>`;}).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h2>SIP backtest</h2><div class="flow-row"><label class="inline">Monthly ₹ <input id="sip-amount" type="number" min="100" max="100000000" step="100" style="width:145px" value="${state.monthly||10000}"></label><button id="calculate-sip">Calculate</button></div></div>${p.sip?`<div class="metrics">${metric('Total invested',money(p.sip.invested),p.sip.payments+' monthly installments')}${metric('Final value',money(p.sip.value),'As of '+D(p.sip.end))}${metric('Gain / loss',`<span class="${cls(p.sip.gain)}">${money(p.sip.gain)}</span>`,'Before tax and exit loads')}${metric('XIRR',P(p.sip.xirr),'Annualized, money-weighted return')}</div><p class="footer-note">${E(p.sip.convention)} SIP calculations use fund dates, independently of benchmark availability. No future results are projected.</p>`:empty('SIP results unavailable','Growth NAV history or complete reinvestment-adjusted IDCW history is required.')}</section>${p.stats.gaps?.length?`<div class="callout warning">${p.stats.gaps.length} gaps longer than seven calendar days exist in the saved NAV history. Missing days are not filled with estimated NAVs; volatility excludes returns across these gaps.</div>`:''}`;
  $('[data-range]')&&document.querySelectorAll('[data-range]').forEach(b=>b.addEventListener('click',()=>{state.range=b.dataset.range;refreshPerformance();}));
  $('#chart-mode').addEventListener('change',e=>{state.chartMode=e.target.value;performanceChart();});$('#benchmark-select').addEventListener('change',e=>{state.benchmark=e.target.value;refreshPerformance();});
  $('#apply-range').addEventListener('click',()=>{state.range='Custom';state.customStart=$('#range-start').value;state.customEnd=$('#range-end').value;refreshPerformance();});
  $('#calculate-sip').addEventListener('click',()=>{state.monthly=Number($('#sip-amount').value);refreshPerformance();});performanceChart();
}
async function refreshPerformance(){try{const token=state.token;$('#fund-content').style.opacity='.65';const p=await getPerformance();if(token!==state.token)return;state.perf=p;renderPerformance();}catch(e){toast(e.message);}finally{if($('#fund-content'))$('#fund-content').style.opacity='1';}}
function performanceChart(){const p=state.perf;let points=[],series=[{label:'Fund',color:'#205ade'}],opts={},msg='';
  if(state.chartMode==='nav'){points=p.nav;series=[{label:'NAV',color:'#205ade'}];opts.currency=true;if(state.fund.option!=='Growth')msg='This chart shows NAV per unit only. Distributions reduce IDCW NAV; it is not a total-return chart.';}
  else if(state.chartMode==='drawdown'){points=p.range_stats.drawdown;opts.percent=true;series=[{label:'Drawdown',color:'#b33b49'}];}
  else if(state.chartMode==='rolling'){points=p.stats.rolling.filter(x=>(!rangeStart()||x[0]>=rangeStart())&&(!state.customEnd||state.range!=='Custom'||x[0]<=state.customEnd));opts.percent=true;series=[{label:'Rolling 3Y CAGR',color:'#087d67'}];}
  else{points=p.comparison;series=[{label:'Fund · rebased 100',color:'#205ade'},{label:state.benchmark+' · rebased 100',color:'#dd7940'}];if(!p.can_total_return)msg='A total-return comparison requires complete IDCW distribution history. Use the NAV view, or import complete payout data.';else if(!points.length)msg='The selected benchmark has no matching TRI history. Import an official TRI CSV in Data & archive. Fund returns remain available in the overview.';}
  $('#chart-message').innerHTML=msg?`<div class="callout warning section-space">${E(msg)} <a href="#/archive">Data & archive →</a></div>`:'';
  $('#performance-legend').innerHTML=series.map(s=>`<span><i class="legend-line" style="background:${s.color}"></i>${E(s.label)}</span>`).join('');drawChart($('#performance-chart'),points,series,opts);$('#chart-interval').textContent=points.length?D(points[0][0])+' – '+D(points.at(-1)[0]):'';
}

async function renderPortfolio(){const f=state.fund;const el=$('#fund-content');if(!f.portfolios.length){el.innerHTML=`<section class="panel">${empty('No parsed portfolio snapshot yet','Original portfolio documents may already be in Fund communications. Import a holdings CSV to add a dated snapshot.',`<a class="primary-link" href="#/archive">Import a portfolio</a> <a class="secondary-link" href="#/fund/${f.code}/news">Open disclosures →</a>`)}</section>`;return;}
  el.innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Portfolio history</h2><div class="small muted">Holdings are shared across plans of the same fund.</div></div><label>Snapshot<select id="snapshot-picker">${f.portfolios.map(p=>`<option value="${p.id}">${D(p.as_of)} · ${p.complete?'complete':'partial'} · ${p.holding_count} holdings</option>`).join('')}</select></label></div><div id="holdings-view"></div></section>`;$('#snapshot-picker').addEventListener('change',e=>loadHoldings(e.target.value));await loadHoldings(f.portfolios[0].id);
}
async function loadHoldings(id){try{const token=state.token;const p=await api('/api/portfolios/'+id);if(token!==state.token)return;const total=p.holdings.reduce((s,x)=>s+x.weight,0),sectors={};for(const h of p.holdings){const k=h.sector||'Sector not supplied';sectors[k]=(sectors[k]||0)+h.weight;}
  $('#holdings-view').innerHTML=`<div class="callout ${p.complete?'':'warning'}">${p.complete?'Complete portfolio as supplied.':'Partial disclosed holdings. Omitted securities, cash and other assets cannot be treated as zero.'} Weights are percentages of fund net assets. ${sourceLink(p.source)}</div><div class="mini-stats"><div><span>Reporting date</span><strong>${D(p.as_of)}</strong></div><div><span>Disclosed positions</span><strong>${p.holdings.length}</strong></div><div><span>Disclosed weight</span><strong>${N(total)}%</strong></div></div><div class="flow-row section-space"><a class="secondary-link" href="/api/export/portfolio/${p.id}">Download holdings CSV ↓</a></div><div class="table-wrap section-space"><table><thead><tr><th>Holding</th><th>Sector / asset</th><th>ISIN</th><th class="right">% of net assets</th></tr></thead><tbody>${p.holdings.map(h=>`<tr><td><b>${E(h.name)}</b></td><td>${E(h.sector||h.asset_type)}</td><td class="small muted">${E(h.isin||'—')}</td><td class="right">${N(h.weight)}%<div class="weight-bar" style="margin-left:auto"><span style="width:${Math.min(100,Math.abs(h.weight)*10)}%"></span></div></td></tr>`).join('')}</tbody></table></div><div class="two-columns equal section-space"><div><h2>Sector allocation · disclosed holdings</h2><table><tbody>${Object.entries(sectors).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<tr><td>${E(k)}</td><td class="right">${N(v)}%</td></tr>`).join('')}</tbody></table></div><div><h2>Changes since ${p.previous?D(p.previous.as_of):'previous snapshot'}</h2>${p.previous?`<p class="small muted">Changes in weight are percentage points. Weight changes alone do not establish purchases or sales.</p><div class="table-wrap"><table><thead><tr><th>Holding</th><th>Change</th><th class="right">Δ weight</th></tr></thead><tbody>${p.changes.map(x=>`<tr><td>${E(x.name)}</td><td class="small">${E(x.type)}</td><td class="right ${cls(x.change)}">${N(x.change)} pp</td></tr>`).join('')||'<tr><td colspan="3">No disclosed weight changes.</td></tr>'}</tbody></table></div>`:'<p class="muted small">A second snapshot with the same completeness level is needed. Historical files can be imported.</p>'}</div></div>`;
  }catch(e){toast(e.message);}}

const metricNames={aum:'Fund AUM',ter:'Total expense ratio',ter_observed:'TER · observed on website',base_expense_ratio:'Base expense ratio',base_ter:'Base TER (legacy reporting)',brokerage:'Brokerage cost',transaction_cost:'Transaction cost',statutory_levies:'Statutory levies',exit_load:'Exit load',benchmark:'Stated benchmark',managers:'Fund managers',fund_launch:'Fund launch',plan_launch:'Plan launch',objective:'Investment objective',risk:'Risk level',minimum_sip:'Minimum SIP',minimum_lumpsum:'Minimum lumpsum',stated_expense_maximum:'Stated maximum expense · scheme summary'};
function renderFees(){const f=state.fund,m=f.metrics;const hist=f.metric_history.filter(x=>x.plan==='All'||x.plan===f.plan);const fees=hist.filter(x=>['ter','ter_observed','base_expense_ratio','brokerage','transaction_cost','statutory_levies','stated_expense_maximum'].includes(x.metric));const aum=hist.filter(x=>x.metric==='aum');
  $('#fund-content').innerHTML=`<div class="two-columns equal"><section class="panel"><div class="panel-head"><h2>AUM history</h2><span class="small muted">₹ crore · whole fund</span></div><div id="aum-chart"></div></section><section class="panel"><div class="panel-head"><h2>Expense ratio history</h2><span class="small muted">${E(f.plan)} plan · % p.a.</span></div><div id="fee-legend" class="chart-legend"></div><div id="fee-chart"></div></section></div><section class="panel"><h2>Exit load</h2><div class="text-block">${metricValue(m.exit_load)}</div>${m.exit_load?`<p class="footer-note">Observed ${D(m.exit_load.as_of)} · ${sourceLink(m.exit_load.source)}. Load terms may vary by purchase date; use the applicable original disclosure.</p>`:''}</section><section class="panel no-pad"><div class="panel-head table-head"><div><h2>Fees & dated records</h2><p class="small muted">Reported dates and observation dates are kept distinct.</p></div><a href="/api/export/metrics/${f.code}" class="secondary-link">Export history ↓</a></div>${hist.length?`<div class="table-wrap"><table><thead><tr><th>Metric</th><th>Plan</th><th>Date</th><th>Value</th><th>Source</th></tr></thead><tbody>${hist.map(r=>`<tr><td>${E(metricNames[r.metric]||r.metric)}</td><td>${E(r.plan)}</td><td class="nowrap">${D(r.as_of)}<div class="fund-detail">${E(r.unit)}</div></td><td style="max-width:460px">${E(r.value)}</td><td>${sourceLink(r.source)}<div class="fund-detail">Saved ${T(r.observed_at)}</div></td></tr>`).join('')}</tbody></table></div>`:empty('No numeric records have been extracted yet','Use the fund’s official documents or import dated AUM and fee records.',`<a class="primary-link" href="#/archive">Import records</a>`)}</section><div class="callout">A scheme-summary “stated maximum expense” is kept separately from an actual TER. Undated website TER values are labelled by when they were observed. AUM and fee history starts with available reports; missing periods are never estimated.</div>`;
  function unique(rs){const map={};rs.forEach(r=>{if(!(r.as_of in map))map[r.as_of]=Number(r.value);});return Object.entries(map).sort((a,b)=>a[0].localeCompare(b[0]));}
  drawChart($('#aum-chart'),unique(aum),[{label:'AUM · ₹ Cr',color:'#205ade'}],{sparse:true});
  const feeSeries=[{key:'ter',label:'TER · reported',color:'#087d67'},{key:'ter_observed',label:'TER · observed',color:'#205ade'},{key:'base_expense_ratio',label:'BER · reported',color:'#a2670c'}].filter(x=>fees.some(r=>r.metric===x.key));
  const feeMaps=feeSeries.map(s=>new Map(unique(fees.filter(x=>x.metric===s.key))));
  const feeDates=[...new Set(feeMaps.flatMap(m=>[...m.keys()]))].sort();
  $('#fee-legend').innerHTML=feeSeries.map(s=>`<span><i class="legend-line" style="background:${s.color}"></i>${E(s.label)}</span>`).join('');
  drawChart($('#fee-chart'),feeDates.map(d=>[d,...feeMaps.map(m=>m.get(d)??null)]),feeSeries,{percent:true,sparse:true});
}
function renderNews(docs){docs=docs.filter(d=>d.kind!=='news');const f=state.fund;$('#fund-content').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Fund communications</h2><div class="small muted">${E(f.family)} · Publications from the mutual fund</div></div>${HOSTED?projectLink('/actions/workflows/daily.yml','Check for updates'):'<button id="refresh-news">↻ Check publications</button>'}</div><div class="chip-list" id="news-filters">${['All','Factsheets','Portfolio','Market views','Disclosures','Source pages'].map(k=>`<button data-filter="${k}" class="${state.newsFilter===k?'active':''}">${k}</button>`).join('')}</div><div id="doc-list" class="doc-list"></div></section><p class="footer-note">Publication dates are shown only when supplied by the source. “First found” is the tracker’s discovery date. AMC-wide commentary is labelled separately from fund-specific material. Archives retain versions from the time they are first downloaded.</p>`;
  const filters={'Factsheets':['factsheet'],'Portfolio':['portfolio'],'Market views':['market view'],'Disclosures':['disclosure','scheme document'],'Source pages':['source page']};
  function list(){const rows=docs.filter(d=>state.newsFilter==='All'?d.kind!=='source page':filters[state.newsFilter]?.includes(d.kind));$('#doc-list').innerHTML=rows.map(d=>`<article class="doc-card"><div class="doc-icon">${d.kind==='portfolio'?'HOLD':'DOC'}</div><div class="doc-body"><div class="doc-top"><span class="badge blue">${E(d.kind)}</span><span class="badge">${d.scope==='AMC'?'Fund-house-wide':'Fund-specific'}</span>${d.versions.length?`<span class="badge green">${d.versions.length} saved version${d.versions.length===1?'':'s'}</span>`:''}</div><a class="doc-title" href="${E(d.url)}" target="_blank" rel="noopener noreferrer">${E(d.title)} ↗</a><div class="doc-meta">${E(d.origin)} · ${d.published_at?'Published '+D(d.published_at):'Publication date not supplied · first found '+D(d.first_seen)}</div><div class="doc-actions">${sourceLink(d.url,'Open original')}${d.versions.length?`<a href="/api/archive/${d.versions[0].hash}">Download saved copy ↓</a><details><summary>Version history</summary><div class="version-list">${d.versions.map(v=>`<a href="/api/archive/${v.hash}">${T(v.observed_at)} · ${N(v.bytes/1024,0)} KB</a>`).join('')}</div></details>`:'<span class="muted">Link retained · file not yet archived</span>'}</div></div></article>`).join('')||empty('No items in this view yet','The updater checks the configured official fund sources. Older documents appear as they are discovered or added.');}
  document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{state.newsFilter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));list();}));$('#refresh-news')?.addEventListener('click',async()=>{try{await post('/api/refresh',{kind:'documents'});toast('Official publication checks started.');}catch(e){toast(e.message);}});list();
}

function renderArchive(){if(HOSTED){renderHostedArchive();return;}document.title='Data & archive · Smallcap Ledger';$('#breadcrumb').textContent='Research / Data & archive';const c=state.status?.counts||{};
  $('#main').innerHTML=`<div class="page-heading"><div><div class="eyebrow">Your historical record</div><h1>Data & archive</h1><p>Inspect coverage, add dated records, and back up your saved history.</p></div><div class="page-actions"><a class="primary-link" href="/api/export/backup">Download data backup ↓</a></div></div><div id="busy-area">${busy()}</div><div class="metrics">${metric('NAV observations',N(c.nav_points||0,0),'Source and observation time retained',true)}${metric('TRI observations',N(c.benchmark_points||0,0),'Actual total-return index levels')}${metric('Portfolio snapshots',N(c.portfolios||0,0),'Dated, with completeness labels')}${metric('Source archive',N((c.archive_bytes||0)/1048576,1)+' MB','Files deduplicated by content')}</div><section class="panel"><div class="panel-head"><h2>Import a historical record</h2><span class="badge">CSV · UTF-8</span></div><p class="small muted">Use the original AMC or index-provider file as your source. The form states the expected units; blank data is never treated as zero.</p><form id="import-form" class="form-grid"><label>Record type<select name="kind" id="import-kind"><option value="metrics">AUM, fees and fund facts</option><option value="portfolio">Portfolio snapshot</option><option value="benchmark">Benchmark TRI history</option><option value="distributions">IDCW distribution history</option><option value="document">Original fund document</option></select></label><label id="import-scheme-label">Scheme<select name="code" id="import-code">${state.funds.map(f=>`<option value="${f.code}" ${f.code===state.importCode?'selected':''}>${E(f.family)} · ${E(f.plan)} · ${E(f.option)} (${f.code})</option>`).join('')}</select></label><label class="wide">Original source URL<input name="source" type="url" required placeholder="https://…"></label><div id="import-extra" class="wide"></div><label class="wide">File to import<input name="file" type="file" accept=".csv,text/csv" id="import-file" required></label><div class="wide form-hint" id="import-guide"></div><div class="wide flow-row"><button class="primary" type="submit">Import & retain history</button><a id="import-template" href="/api/templates/metrics">Download blank CSV template ↓</a></div><div id="import-result" class="wide import-result" role="status"></div></form></section><section class="panel"><h2>Benchmark coverage</h2>${(state.status?.benchmarks||[]).length?`<table><thead><tr><th>Total-return index</th><th>First date</th><th>Latest date</th><th class="right">Observations</th></tr></thead><tbody>${state.status.benchmarks.map(x=>`<tr><td>${E(x.name)}</td><td>${D(x.first)}</td><td>${D(x.last)}</td><td class="right">${N(x.points,0)}</td></tr>`).join('')}</tbody></table>`:empty('Benchmark download pending','Automatic collection uses NSE Indices’ public TRI history. BSE or other official TRI CSV files can be imported.')}<p class="footer-note">${sourceLink('https://www.niftyindices.com/reports/historical-data','NSE Indices historical downloads')} · Never import a price index under a TRI label.</p></section><section class="panel"><h2>Recent update activity</h2><div id="logs" class="logs">${logs()}</div></section>`;
  $('#import-kind').addEventListener('change',importGuide);$('#import-form').addEventListener('submit',async e=>{e.preventDefault();const btn=$('button[type=submit]',e.target);btn.disabled=true;$('#import-result').textContent='Validating and saving…';try{const r=await api('/api/import',{method:'POST',body:new FormData(e.target)});$('#import-result').textContent=r.note||`Saved ${r.rows} rows. Open the fund page to inspect the result.`;await pollStatus();}catch(err){$('#import-result').textContent=err.message;}finally{btn.disabled=false;}});importGuide();
}
function importGuide(){const k=$('#import-kind').value;$('#import-template').href='/api/templates/'+k;$('#import-scheme-label').style.display=k==='benchmark'?'none':'';let extra='',hint='';
  if(k==='metrics')hint='Columns: <code>metric,plan,as_of,value</code>. Dates: YYYY-MM-DD. AUM: <code>aum</code> in ₹ crore, plan <code>All</code>. Fees: <code>ter</code>, <code>base_expense_ratio</code>, <code>brokerage</code>, <code>transaction_cost</code>, <code>statutory_levies</code> in percentage points per year (0.65 means 0.65%), with plan Direct or Regular. Text fields: <code>exit_load</code>, <code>benchmark</code>, <code>managers</code>, <code>objective</code>, <code>fund_launch</code>, <code>risk</code>. Imported dates mean reported/effective dates.';
  if(k==='portfolio'){extra='<label>Portfolio reporting date<input type="date" name="as_of" required></label><label class="inline section-space"><input type="checkbox" name="complete" value="true">This is the full portfolio, including cash and other assets.</label>';hint='Columns: <code>isin,name,sector,weight,asset_type</code>. Weight is a percentage of fund net assets: 2.5 means 2.5%. Use asset types such as Equity, Cash, Debt or Derivative. ISIN and sector can be blank. Partial files are accepted and labelled; a full file should total approximately 100%.';}
  if(k==='benchmark'){extra='<label>Total-return index name<input name="benchmark" required value="Nifty Smallcap 250 TRI" list="benchmark-names"><datalist id="benchmark-names"><option>Nifty Smallcap 250 TRI</option><option>BSE 250 SmallCap TRI</option><option>Nifty Smallcap 100 TRI</option></datalist></label>';hint='Columns: <code>date,value</code>. Use YYYY-MM-DD dates and the official total-return index level. Do not use an ETF NAV, price index, cumulative percentage return, or net-return series as a TRI substitute.';}
  if(k==='distributions'){extra='<div class="form-grid"><label>Complete history from<input type="date" name="coverage_from" required></label><label>Complete history through<input type="date" name="coverage_to" required></label><label class="inline wide"><input name="complete" type="checkbox" value="true" required>I confirm every distribution in this interval is included, using the applicable reinvestment NAV.</label></div>';hint='Select the exact IDCW plan. Columns: <code>ex_date,amount,reinvestment_nav</code>. Amount is rupees per unit, before tax. Dates are YYYY-MM-DD. The app computes hypothetical reinvested total returns only inside the confirmed interval. This does not represent the cash balance of a payout investor.';}
  if(k==='document'){extra='<div class="form-grid"><label>Document title<input name="title" placeholder="Monthly factsheet"></label><label>Document type<select name="document_kind"><option value="factsheet">Factsheet</option><option value="portfolio">Portfolio</option><option value="disclosure">Disclosure / notice</option><option value="scheme document">Scheme summary / SID / KIM</option><option value="market view">Newsletter / market view</option></select></label><label>Applies to<select name="scope"><option value="Fund">This fund</option><option value="AMC">Whole fund house</option></select></label></div>';hint='Upload an original PDF, Excel, XML or CSV file. Its unchanged bytes and later versions are retained inside the selected fund’s Fund communications tab. Recognized factsheet and portfolio layouts are parsed; unsupported layouts remain downloadable.';}$('#import-file').accept=k==='document'?'.pdf,.xls,.xlsx,.xml,.csv':'.csv,text/csv';$('#import-template').style.display=k==='document'?'none':'';$('#import-extra').innerHTML=extra;$('#import-guide').innerHTML=hint;
}
function logs(){return (state.status?.jobs||[]).map(j=>`<div class="log"><div class="flow-row"><b>${E(j.kind)}</b><span class="badge ${j.status==='ok'?'green':j.status==='running'?'blue':'amber'}">${E(j.status)}</span><span class="muted">${T(j.started_at)}</span></div><details><summary>${E((j.detail||'Update in progress').split('\n')[0])}</summary><pre>${E(j.detail||'')}</pre></details></div>`).join('')||'<p class="muted">No updates yet.</p>';}
function projectLink(path,label){const repo=window.SMALLCAP_CONFIG?.repository;return repo?sourceLink('https://github.com/'+repo+path,label):'<span class="muted">'+E(label)+' · available after deployment</span>';}
function benchmarkCoverage(){return `<section class="panel"><h2>Benchmark coverage</h2><div class="table-wrap"><table><thead><tr><th>Total-return index</th><th>First date</th><th>Latest date</th><th class="right">Observations</th></tr></thead><tbody>${(state.status?.benchmarks||[]).map(x=>`<tr><td>${E(x.name)}</td><td>${D(x.first)}</td><td>${D(x.last)}</td><td class="right">${N(x.points,0)}</td></tr>`).join('')}</tbody></table></div><p class="footer-note">The comparison chart labels a category comparator when the fund’s stated index is unavailable. BSE TRI history and historical benchmark changes may remain gaps.</p></section>`;}
function renderHostedArchive(){const c=state.status?.counts||{};document.title='Data & archive · Smallcap Ledger';$('#breadcrumb').textContent='Research / Data & archive';$('#main').innerHTML=`<div class="page-heading"><div><div class="eyebrow">Your historical record</div><h1>Data & archive</h1><p>Dated figures, original fund publications, and a cumulative historical archive.</p></div><div class="page-actions">${projectLink('/releases/tag/tracker-history','Download full archive ↓')}</div></div><div class="metrics">${metric('NAV observations',N(c.nav_points||0,0),'Dates and sources retained',true)}${metric('TRI observations',N(c.benchmark_points||0,0),'Actual total-return index levels')}${metric('Portfolio snapshots',N(c.portfolios||0,0),'Dated with completeness labels')}${metric('Source archive',N((c.archive_bytes||0)/1048576,1)+' MB','Original files and their versions')}</div><section class="panel"><h2>Download and inspect</h2><p>Each fund page provides NAV, AUM and fee CSV downloads. Fund communications contains the mutual fund’s own publications, with original links and saved versions where available.</p><p class="small muted">The complete archive includes SQLite data and source files. Every daily run restores the previous archive before collecting new observations. Missing or blocked sources retain the last known record and its original reporting date.</p><div class="coverage-grid">${[['Funds with AUM',`${c.aum_funds||0} / ${c.funds||0}`],['Funds with expense figures',`${c.fee_funds||0} / ${c.funds||0}`],['Plans and options',N(c.plans||0,0)],['Website last built',T(state.status?.server_time)]].map(([a,b])=>`<div class="coverage-item"><b>${E(a)}</b><span>${E(b)}</span></div>`).join('')}</div></section>${benchmarkCoverage()}<section class="panel"><h2>Add missing records</h2><p class="small muted">The site owner can import official CSV files or publications in the included local edition, then run the archive import workflow to publish the updated archive. The setup guide explains this process. Visitors can download and compare data without an account.</p>${projectLink('/blob/main/GITHUB-SETUP.md','Open the setup guide')}</section><section class="panel"><div class="panel-head"><h2>Recent update activity</h2>${projectLink('/actions/workflows/daily.yml','View workflow runs')}</div><div id="logs" class="logs">${logs()}</div></section>`;}
function renderHostedSettings(){document.title='Update settings · Smallcap Ledger';$('#breadcrumb').textContent='Research / Update settings';$('#main').innerHTML=`<div class="page-heading"><div><div class="eyebrow">Automatic daily updates</div><h1>Updates while you’re away.</h1><p>The updater runs on GitHub, even when your browser and computer are off.</p></div></div><section class="panel settings-card"><h2>Daily schedule</h2><dl class="facts"><div class="fact"><dt>Scheduled start</dt><dd>Midnight · 00:00 IST</dd></div><div class="fact"><dt>Time zone</dt><dd>Asia/Kolkata</dd></div><div class="fact"><dt>Latest website build</dt><dd>${T(state.status?.server_time)}</dd></div><div class="fact"><dt>Provider</dt><dd>GitHub Pages + GitHub Actions</dd></div></dl><p class="small muted">Midnight is the requested start time. GitHub may queue or occasionally skip a scheduled run; fetching and publishing also take time. Each figure keeps its own reporting date. AMCs usually publish AUM and portfolios less frequently than NAV.</p><p>${projectLink('/actions/workflows/daily.yml','Run an extra update')} · ${projectLink('/blob/main/.github/workflows/daily.yml','Edit the schedule')}</p></section><section class="panel"><h2>Connected sources</h2><p class="small muted">NAV: AMFI, with historical NAV backfill from MFapi. Expense figures: AMC reports via AMFI. AUM: dated official fund-house reports where available. Benchmark levels: NSE Indices. Fund communications: official fund-house sources only. A checked page does not guarantee every field or document was extracted.</p><div class="table-wrap"><table><thead><tr><th>Fund house / source</th><th>Last checked</th><th>Coverage</th></tr></thead><tbody>${(state.status?.sources||[]).map(x=>`<tr><td><b>${E(x.amc_match)}</b><div class="source-url">${sourceLink(x.url,x.label)}</div></td><td class="small nowrap">${T(x.last_checked)}</td><td><span class="badge ${['Gap','Partial','Limited','Pending','Excluded'].includes(x.status)?'amber':'green'}">${E(x.status)}</span><div class="fund-detail" style="max-width:430px">${E(x.detail||'Awaiting a check')}</div></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>Manage the tracker</h2><p class="small muted">Source configuration and schedule changes are made in the repository. The setup guide includes deployment, manual imports, recovery, coverage limits and changing the time zone.</p>${projectLink('/blob/main/GITHUB-SETUP.md','Open setup and maintenance guide')}</section>`;}
function renderSettings(){const s=state.status?.settings||{};document.title='Update settings · Smallcap Ledger';$('#breadcrumb').textContent='Research / Update settings';$('#main').innerHTML=`<div class="page-heading"><div><div class="eyebrow">Local updates</div><h1>Keep the record growing.</h1><p>The app checks published data while its Windows command window is running.</p></div></div><div id="busy-area">${busy()}</div><section class="panel settings-card"><h2>Update schedule</h2><form id="settings-form" class="form-grid"><label class="inline wide"><input type="checkbox" name="auto_update" ${s.auto_update!==false?'checked':''}>Keep automatic updates enabled</label><label>NAV checks · minutes<input type="number" name="nav_interval_minutes" min="30" max="1440" value="${s.nav_interval_minutes||60}" required></label><label>Fund documents · hours<input type="number" name="disclosure_interval_hours" min="6" max="168" value="${s.disclosure_interval_hours||12}" required></label><div class="form-hint">Benchmark checks run every six hours. NAV backfill runs on the next daily update, including dates missed while the app was off.</div><div class="wide"><button type="submit" class="primary">Save schedule</button></div></form><p class="footer-note">Stopping the app or putting Windows to sleep pauses collection. Cached data remains available on the next launch. Website access failures retain previous records. This app does not trade or connect to investment accounts.</p></section><section class="panel"><div class="panel-head"><h2>Fund-house sources</h2><button id="check-docs">↻ Check documents</button></div><p class="small muted">Source pages are starting points for discovery. A successful page check does not mean every document or numeric field was extracted. Blocked, dynamic, missing and unparsed content remains a visible coverage gap.</p><div class="table-wrap"><table><thead><tr><th>Enabled</th><th>Fund house / source</th><th>Last check</th><th>Result</th></tr></thead><tbody>${(state.status?.sources||[]).map(x=>`<tr><td><input type="checkbox" data-source="${x.id}" aria-label="Enable ${E(x.label)} for ${E(x.amc_match)}" ${x.enabled?'checked':''}></td><td><b>${E(x.amc_match)}</b><div class="source-url">${sourceLink(x.url,x.label)}</div></td><td class="small nowrap">${T(x.last_checked)}</td><td><span class="badge ${x.status==='Gap'?'amber':''}">${E(x.status)}</span><div class="fund-detail" style="max-width:430px">${E(x.detail||'Awaiting the next check')}</div></td></tr>`).join('')}</tbody></table></div></section><section class="panel settings-card"><h2>Add a public fund-house page</h2><form id="source-form" class="form-grid"><label>Fund-house name contains<input name="amc_match" required placeholder="For example: HDFC"></label><label>Source label<input name="label" required placeholder="Monthly portfolios"></label><label class="wide">Public URL<input name="url" type="url" required placeholder="https://…"></label><div class="wide"><button type="submit">Add source</button></div></form></section><section class="panel settings-card"><h2>Where your records live</h2><p class="small">${E(state.status?.data_location||'The app’s data folder')}</p><p class="small muted">Backups contain the database and original archived files. Before restoring a backup, close the tracker and copy its data folder into this app’s folder.</p><a class="secondary-link" href="/api/export/backup">Download a data backup ↓</a></section>`;
  $('#settings-form').addEventListener('submit',async e=>{e.preventDefault();const d=new FormData(e.target);try{await post('/api/settings',{auto_update:d.has('auto_update'),nav_interval_minutes:Number(d.get('nav_interval_minutes')),disclosure_interval_hours:Number(d.get('disclosure_interval_hours'))});toast('Update schedule saved.');await pollStatus();}catch(err){toast(err.message);}});
  $('#source-form').addEventListener('submit',async e=>{e.preventDefault();try{await post('/api/sources',Object.fromEntries(new FormData(e.target)));await pollStatus();renderSettings();toast('Source added. It will be checked on the next document update.');}catch(err){toast(err.message);}});
  document.querySelectorAll('[data-source]').forEach(x=>x.addEventListener('change',async()=>{try{await post('/api/sources/'+x.dataset.source,{enabled:x.checked});toast('Source setting saved.');}catch(e){x.checked=!x.checked;toast(e.message);}}));
  $('#check-docs').addEventListener('click',async()=>{try{await post('/api/refresh',{kind:'documents'});toast('Document checks started.');}catch(e){toast(e.message);}});
}

async function pollStatus(){const previous=state.status;state.status=await api('/api/status');if($('#busy-area'))$('#busy-area').innerHTML=busy();if($('#logs'))$('#logs').innerHTML=logs();const before=previous?.running||{},after=state.status.running||{};const done=Object.keys(before).some(k=>!(k in after))||(HOSTED&&previous&&previous.server_time!==state.status.server_time);if(done){toast('An update finished. New records are now available.');if(!['archive','settings'].includes((location.hash||'').split('/')[1]))await route();}else if(state.funds.length===0&&state.status.counts.plans>0&&(location.hash==='#/'||!location.hash)){await loadFunds();renderDashboard();}}
shell();
(async()=>{try{await pollStatus();await route();}catch(e){$('#main').innerHTML=empty(HOSTED?'Saved data could not be loaded':'The local app is not responding',(HOSTED?'Refresh the page or check the latest deployment. ':'Keep START-WINDOWS.cmd running, then refresh this page. ')+e.message);}setInterval(()=>pollStatus().catch(()=>{if($('#busy-area'))$('#busy-area').innerHTML='<div class="callout warning">'+(HOSTED?'Could not check the latest published data. Refresh when your connection returns.':'Connection to the local app was lost. Reopen START-WINDOWS.cmd to resume updates.')+'</div>';}),HOSTED?300000:7000);})();
window.addEventListener('hashchange',route);

